#include <stdio.h>
/* ex09：SSD 的写放大（WAF）与寿命估算
 * 闪存必须「先擦除再写」，且擦除单位（块，如 512KB）远大于写单位（页，4KB）。
 * 随机写会让一个擦除块里既有有效页又有垃圾 -> 需要 GC：搬有效页 + 擦块
 * -> 实际写入量 > 用户写入量，比值就是 WAF（Write Amplification Factor）。
 * 寿命 ≈ 总可写量(TBW) / 实际年写入量。*/
int main(void) {
    double user_gb_day = 50.0;     /* 每天写入 50GB */
    double tbw = 600.0;            /* 厂商标称 600 TBW */
    double waf_random = 3.0;       /* 随机小写：放大 3 倍 */
    double waf_seq = 1.1;          /* 顺序大写：几乎不放大 */

    double year_random = tbw * 1024 / (user_gb_day * 365 * waf_random);
    double year_seq    = tbw * 1024 / (user_gb_day * 365 * waf_seq);

    printf("每天写入 %.0fGB，标称 TBW=%.0fTB\n", user_gb_day, tbw);
    printf("--------------------------------------------------\n");
    printf("%-14s %-10s %-14s %s\n", "写模式", "WAF", "实际日写入", "预计寿命(年)");
    printf("%-14s %-10.1f %-14.1f %.1f\n", "随机小写", waf_random,
           user_gb_day * waf_random, year_random);
    printf("%-14s %-10.1f %-14.1f %.1f\n", "顺序大写", waf_seq,
           user_gb_day * waf_seq, year_seq);
    printf("--------------------------------------------------\n");
    printf("随机写让寿命缩短 %.1f 倍\n", year_seq / year_random);
    printf("\n工程结论：\n");
    printf("  1) SSD 上要尽量顺序写（日志结构、LSM、append-only）；\n");
    printf("  2) 留足 OP（over-provisioning，预留 7%%~28%%）能显著降低 WAF；\n");
    printf("  3) TRIM 让文件系统告诉 SSD「这些页没用了」，GC 才不会白搬垃圾。\n");
    return 0;
}
